56	/// The first `Ecosystem::CANONICAL` ecosystem whose canonical manifest
57	/// exists at `abs_path`, in `Ecosystem::CANONICAL`'s declared order (Cargo,
58	/// then Npm, then Pypi). Used where a project needs exactly one ecosystem
59	/// (e.g. `declared_edges`'s from/to resolution) -- unlike `projects()`,
60	/// which deliberately enumerates every canonical ecosystem present, since a
61	/// single project directory can be dual-published (e.g. Cargo + npm).
62	fn detect_single_ecosystem(abs_path: &Path) -> Option<Ecosystem> {
63	    Ecosystem::CANONICAL.into_iter().find(|eco| {
64	        let format = eco
65	            .canonical_manifest_format()
66	            .expect("CANONICAL ecosystems always have a canonical manifest format");
67	        abs_path.join(format.file_name()).exists()
68	    })
69	}
