108	pub fn scope_to_declared_edge_kind(scope: DependencyScope) -> DeclaredEdgeKind {
109	    match scope {
110	        DependencyScope::Build => DeclaredEdgeKind::Build,
111	        DependencyScope::Development => DeclaredEdgeKind::Development,
