118	impl<'a, R: CommandRunner> ProjectLocator for MoonProjectLocator<'a, R> {
119	    fn projects(&self) -> Result<Vec<ProjectRoot>, LocateError> {
120	        let graph = self.load_graph()?;
121	        let mut roots = Vec::new();
122	
123	        for project in graph.data.values() {
124	            // Use `source` (workspace-relative) rather than `root` (host-absolute).
125	            // In the WASM PDK context moon's `root` carries host-absolute paths
126	            // that are not in the same virtual-filesystem namespace as the
127	            // `/workspace/`-anchored `workspace_root` the moon host passes to
128	            // the extension. Using `source` works correctly in both WASM and
129	            // native environments.
130	            let rel_path = PathBuf::from(&project.source);
131	            let abs_path = self.workspace_root.join(&rel_path);
132	
133	            if !abs_path.starts_with(&self.workspace_root) {
134	                return Err(LocateError::OutsideWorkspaceRoot {
135	                    path: abs_path,
136	                    root: self.workspace_root.clone(),
137	                });
138	            }
139	
140	            // Every canonical ecosystem present is reported -- a single
141	            // project directory can be dual-published (e.g. Cargo + npm),
142	            // unlike `declared_edges`'s single-ecosystem-per-project lookup
143	            // below, which only needs one identity per edge endpoint.
144	            for ecosystem in Ecosystem::CANONICAL {
145	                let format = ecosystem
146	                    .canonical_manifest_format()
147	                    .expect("CANONICAL ecosystems always have a canonical manifest format");
148	                if abs_path.join(format.file_name()).exists() {
149	                    let id = self.resolve_id(&abs_path, ecosystem)?;
150	                    roots.push(ProjectRoot {
151	                        id,
152	                        path: rel_path.clone(),
153	                        ecosystem,
154	                    });
155	                }
156	            }
157	        }
158	
159	        Ok(roots)
160	    }
161	
162	    fn declared_edges(&self) -> Option<Vec<DeclaredEdge>> {
163	        let graph = self.load_graph().ok()?;
164	
165	        // Build a lookup from moon project ID to project for dependency resolution.
166	        let id_to_project: HashMap<&str, &MoonProject> = graph.data.values().map(|p| (p.id.as_str(), p)).collect();
167	
168	        let mut edges = Vec::new();
169	
170	        for project in graph.data.values() {
171	            let abs_from = self.workspace_root.join(&project.source);
172	
173	            let Some(from_eco) = detect_single_ecosystem(&abs_from) else {
174	                continue;
175	            };
176	
177	            for dep in &project.dependencies {
178	                let Some(to_project) = id_to_project.get(dep.id.as_str()) else {
179	                    continue;
180	                };
181	
182	                let abs_to = self.workspace_root.join(&to_project.source);
183	
184	                let Some(to_eco) = detect_single_ecosystem(&abs_to) else {
185	                    continue;
186	                };
187	
188	                if let (Ok(from), Ok(to)) = (self.resolve_id(&abs_from, from_eco), self.resolve_id(&abs_to, to_eco)) {
189	                    edges.push(DeclaredEdge {
190	                        from,
191	                        to,
192	                        kind: scope_to_declared_edge_kind(dep.scope),
193	                        via: dep.via.clone(),
194	                    });
195	                }
196	            }
197	        }
198	
199	        Some(edges)
200	    }
201	}
