248	#[derive(Clone, Debug, Default)]
249	pub struct IdentityIndex {
250	    pub bare: BTreeMap<String, PackageId>,
251	    pub prefixed: BTreeMap<(Ecosystem, String), PackageId>,
252	    pub native: BTreeMap<(Ecosystem, String), PackageId>,
253	    /// Keyed by a platform npm manifest's own package name (e.g.
254	    /// `"@myorg/my-crate-linux-x64-gnu"`) -- distinct from `owner`'s name
255	    /// when the owning package's primary identity comes from a
256	    /// higher-priority ecosystem sharing the same directory (a Cargo+npm
257	    /// Case D project, §M.6.1 M7: platform manifests belong to the owning
258	    /// `Package`, they are never independently-registered `Package`s of
259	    /// their own). The `ManifestRole::Platform` is carried alongside so
260	    /// `GroupTable::resolve` doesn't need a second disk read to recover it.
261	    pub platform: BTreeMap<String, (PackageId, PathBuf, ManifestRole)>,
262	}
263	
264	impl IdentityIndex {
265	    pub fn resolve_human(&self, name: &str, siblings: &[PackageId]) -> Result<PackageId, GraphError> {
266	        if let Ok(PackageId::Prefixed { ecosystem, name: n }) = PackageId::parse(name) {
267	            if let Some(id) = self.prefixed.get(&(ecosystem, n)) {
268	                return Ok(id.clone());
269	            }
270	        }
271	
272	        if let Some(id) = self.bare.get(name) {
273	            return Ok(id.clone());
274	        }
275	
276	        let mut candidates = Vec::new();
277	        for ((_eco, n), id) in &self.prefixed {
278	            if n == name {
279	                candidates.push(id.clone());
280	            }
281	        }
282	
283	        if candidates.len() == 1 {
284	            return Ok(candidates[0].clone());
285	        }
286	
287	        if candidates.len() > 1 && !siblings.is_empty() {
288	            for sib in siblings {
289	                for cand in &candidates {
290	                    if cand.ecosystem() == sib.ecosystem() {
291	                        return Ok(cand.clone());
292	                    }
293	                }
294	            }
295	        }
296	
297	        if candidates.is_empty() {
298	            Err(GraphError::UnknownPackage {
299	                id: PackageId::parse(name).unwrap_or_else(|_| PackageId::Bare(name.to_string())),
300	            })
301	        } else {
302	            Err(GraphError::AmbiguousName {
303	                name: name.to_string(),
304	                candidates,
305	            })
306	        }
307	    }
308	
309	    /// Look up a package by its native (manifest-declared) name.
310	    ///
311	    /// First tries the exact `(eco, name)` key. If that misses -- a
312	    /// package in one ecosystem depending on a different ecosystem's
313	    /// package by bare name (e.g. an npm package listing a cargo crate)
314	    /// -- falls back to scanning all ecosystems for `name`.
315	    ///
316	    /// Fallback finds exactly one match: returns it. Finds more than one
317	    /// (two ecosystems both have `name`): returns `None` to prevent
318	    /// silent misresolution -- callers holding a `&mut Vec<Diagnostic>`
319	    /// should use [`Self::resolve_native_with_fallback`] instead, to get
320	    /// a diagnostic.
321	    pub fn resolve_native(&self, eco: Ecosystem, name: &str) -> Option<&PackageId> {
322	        // Fast path: exact ecosystem match.
323	        if let Some(id) = self.native.get(&(eco, name.to_string())) {
324	            return Some(id);
325	        }
326	
327	        // Cross-ecosystem fallback.
328	        let mut candidates: Vec<&PackageId> = self
329	            .native
330	            .iter()
331	            .filter(|((e, n), _)| *e != eco && n == name)
332	            .map(|(_, id)| id)
333	            .collect();
334	
335	        // Deduplicate by pointer identity (multiple entries for the same ID
336	        // across different ecosystems, e.g. a package that is both cargo and
337	        // npm, should not be treated as ambiguous).
338	        candidates.dedup_by(|a, b| a == b);
339	
340	        match candidates.len() {
341	            1 => Some(candidates[0]),
342	            // 0 = not found; >1 = true ambiguity → caller should diagnose.
343	            _ => None,
344	        }
345	    }
346	
347	    /// Like [`Self::resolve_native`] but pushes a [`callisto_model::Diagnostic`] when
348	    /// cross-ecosystem ambiguity is detected (two packages with the same bare
349	    /// name in different ecosystems).
350	    pub fn resolve_native_with_fallback<'a>(
351	        &'a self,
352	        eco: Ecosystem,
353	        name: &str,
354	        diagnostics: &mut Vec<callisto_model::Diagnostic>,
355	    ) -> Option<&'a PackageId> {
356	        // Fast path: exact ecosystem match.
357	        if let Some(id) = self.native.get(&(eco, name.to_string())) {
358	            return Some(id);
359	        }
360	
361	        // Cross-ecosystem fallback: collect unique IDs from other ecosystems.
362	        let mut candidates: Vec<(Ecosystem, &PackageId)> = self
363	            .native
364	            .iter()
365	            .filter(|((e, n), _)| *e != eco && n == name)
366	            .map(|((e, _), id)| (*e, id))
367	            .collect();
368	        candidates.dedup_by(|a, b| a.1 == b.1);
369	
370	        match candidates.len() {
371	            0 => None,
372	            _ => {
373	                let candidate_names: Vec<String> = candidates
374	                    .iter()
375	                    .map(|(e, id)| format!("{}:{}", e.prefix(), id.name()))
376	                    .collect();
377	                diagnostics.push(callisto_model::Diagnostic {
378	                    code: callisto_model::DiagnosticCode::UnknownPackage,
379	                    severity: callisto_model::DiagnosticSeverity::Warning,
380	                    message: format!(
381	                        "dependency name `{}` is ambiguous across ecosystems: {}; \
382	                         add an ecosystem prefix (e.g. `cargo:{}`) to disambiguate",
383	                        name,
384	                        candidate_names.join(", "),
385	                        name,
386	                    ),
387	                    package: None,
388	                    path: None,
389	                    escalated_by: None,
390	                    governed_by: None,
391	                });
392	                None
393	            }
394	        }
395	    }
