105	
106	        for (rel_path, mut list) in by_path {
107	            // Explicit precedence: Cargo (0) > Npm (1) > Pypi (2) > others.
108	            // Do NOT rely on enum discriminant order -- sort by this named
109	            // priority function so the precedence survives future variant
110	            // additions to `Ecosystem`.
111	            list.sort_by_key(|a| ecosystem_primary_priority(a.0));
112	            let mut primary_id = list[0].1.clone();
113	            let (this_claiming, this_native_keys) = compute_claiming_ecosystems_and_native_keys(&list, &primary_id);
114	            claiming_ecosystems.insert(rel_path.clone(), this_claiming.clone());
115	            path_native_keys.insert(rel_path.clone(), this_native_keys);
116	            primary_ecosystems.insert(rel_path.clone(), list[0].0);
117	
118	            let mut branch_ii_promoted = false;
119	            if let Some(existing_members) = promoted_siblings.get(primary_id.name()) {
120	                let this_set = claiming_ecosystems.get(&rel_path).cloned().unwrap_or_default();
121	                let conflict = existing_members
122	                    .iter()
123	                    .find(|(_, member_set)| !claiming_sets_disjoint(&this_set, member_set));
124	                if let Some((conflicting_id, _)) = conflict {
125	                    let offending_path = package_manifest_decls
126	                        .iter()
127	                        .find(|(id, _)| *id == conflicting_id)
128	                        .map(|(_, (p, _))| p.clone())
129	                        .unwrap_or_default();
130	                    return Err(GraphError::DuplicatePackage {
131	                        id: primary_id,
132	                        paths: vec![offending_path, rel_path],
133	                    });
134	                }
135	                let promoted_id = PackageId::Prefixed {
136	                    ecosystem: primary_ecosystems[&rel_path],
137	                    name: primary_id.name().to_string(),
138	                };
139	                promoted_siblings
140	                    .entry(primary_id.name().to_string())
141	                    .or_default()
142	                    .push((promoted_id.clone(), this_set));
143	                primary_id = promoted_id;
144	                branch_ii_promoted = true;
145	            }
146	
147	            if !branch_ii_promoted {
148	                index.bare.insert(primary_id.name().to_string(), primary_id.clone());
149	            }
150	
151	            let mut decls = Vec::new();
152	            for (eco, id) in &list {
153	                let (fmt, filename) = match eco {
154	                    Ecosystem::Cargo => (ManifestFormat::CargoToml, "Cargo.toml"),
155	                    Ecosystem::Npm => (ManifestFormat::PackageJson, "package.json"),
156	                    Ecosystem::Pypi => (ManifestFormat::PyprojectToml, "pyproject.toml"),
157	                    _ => (ManifestFormat::PackageJson, "package.json"),
158	                };
159	                let manifest_rel = rel_path.join(filename);
160	                if let Ok(decl) = ManifestDecl::new(manifest_rel.clone(), ManifestRole::Canonical, fmt) {
161	                    decls.push(decl);
162	                }
163	                // For napi platform packages (os + cpu constraints in package.json),
164	                // also push a Platform-role decl so plan_publish can route them
165	                // into npm_platform_packages instead of npm_main_packages.
166	                if *eco == Ecosystem::Npm {
167	                    let role = detect_npm_role(&root.join(&manifest_rel));
168	                    if let ManifestRole::Platform { .. } = role {
169	                        if let Ok(platform_decl) = ManifestDecl::new(manifest_rel.clone(), role.clone(), fmt) {
170	                            decls.push(platform_decl);
171	                        }
172	                        // `id` is this manifest's own npm identity, resolved from its
173	                        // own `name` field -- distinct from `primary_id` whenever a
174	                        // higher-priority ecosystem (Cargo) shares this directory
175	                        // (Case D). Config authors reference the platform package by
176	                        // its own name in `[[fixed-group]] members`, so that must be
177	                        // the index key; `primary_id` is who it belongs to.
178	                        index
179	                            .platform
180	                            .insert(id.name().to_string(), (primary_id.clone(), manifest_rel, role));
181	                        path_platform_keys
182	                            .entry(rel_path.clone())
183	                            .or_default()
184	                            .push(id.name().to_string());
185	                    }
186	                }
187	                index.native.insert((*eco, id.name().to_string()), primary_id.clone());
188	                if id.name() == primary_id.name() {
189	                    index.prefixed.insert((*eco, id.name().to_string()), primary_id.clone());
190	                }
191	            }
192	
193	            let current_decls = decls.clone();
194	            if let Some((existing_path, existing_decls)) =
195	                package_manifest_decls.insert(primary_id.clone(), (rel_path.clone(), decls))
196	            {
197	                let name = primary_id.name().to_string();
198	                let existing_set = claiming_ecosystems.get(&existing_path).cloned().unwrap_or_default();
199	                let current_set = claiming_ecosystems.get(&rel_path).cloned().unwrap_or_default();
200	                if !claiming_sets_disjoint(&existing_set, &current_set) {
201	                    return Err(GraphError::DuplicatePackage {
202	                        id: primary_id,
203	                        paths: vec![existing_path, rel_path],
204	                    });
205	                }
206	                // STALE-KEY REWRITE location (4): re-key package_manifest_decls under
207	                // each path's own newly-promoted Prefixed id, sourcing each path's own
208	                // decls -- captured via the `existing_decls` returned by `insert` above
209	                // and the `current_decls` clone taken before `insert` overwrote the map,
210	                // never via a `.get(&primary_id)` lookup after the fact (a lookup miss
211	                // there would silently substitute an empty Vec -- exactly the AC-04
212	                // manifests-bleed bug).
213	                let existing_id = PackageId::Prefixed {
214	                    ecosystem: primary_ecosystems[&existing_path],
215	                    name: name.clone(),
216	                };
217	                let current_id = PackageId::Prefixed {
218	                    ecosystem: primary_ecosystems[&rel_path],
219	                    name: name.clone(),
220	                };
221	                package_manifest_decls.insert(existing_id.clone(), (existing_path.clone(), existing_decls));
222	                package_manifest_decls.insert(current_id.clone(), (rel_path.clone(), current_decls));
223	                package_manifest_decls.remove(&primary_id);
224	                // STALE-KEY REWRITE location (1): once a bare name is promoted,
225	                // it MUST NOT remain in index.bare.
226	                index.bare.remove(&name);
227	                // STALE-KEY REWRITE location (2): update index.native values
228	                // for all native keys declared by either path so they map to
229	                // their path's newly-promoted Prefixed id, not the stale primary_id.
230	                if let Some(keys) = path_native_keys.get(&existing_path) {
231	                    for key in keys {
232	                        index.native.insert(key.clone(), existing_id.clone());
233	                    }
234	                }
235	                if let Some(keys) = path_native_keys.get(&rel_path) {
236	                    for key in keys {
237	                        index.native.insert(key.clone(), current_id.clone());
238	                    }
239	                }
240	                // STALE-KEY REWRITE location (3)/(5): update index.prefixed values
241	                // for the primary identities so they point to the newly-promoted
242	                // Prefixed id rather than the pre-promotion primary_id.
243	                for eco in claiming_ecosystems.get(&existing_path).cloned().unwrap_or_default() {
244	                    index.prefixed.insert((eco, name.clone()), existing_id.clone());
245	                }
246	                for eco in claiming_ecosystems.get(&rel_path).cloned().unwrap_or_default() {
247	                    index.prefixed.insert((eco, name.clone()), current_id.clone());
248	                }
249	                // STALE-KEY REWRITE location (6): update index.platform's owner-id
250	                // component for every platform manifest declared under either path,
251	                // so a platform sibling co-located with a promoted owner keeps
252	                // pointing at that owner's newly-promoted Prefixed id rather than
253	                // the stale pre-promotion primary_id.
254	                if let Some(keys) = path_platform_keys.get(&existing_path) {
255	                    for key in keys {
256	                        if let Some((_, manifest_rel, role)) = index.platform.get(key).cloned() {
257	                            index
258	                                .platform
259	                                .insert(key.clone(), (existing_id.clone(), manifest_rel, role));
260	                        }
261	                    }
262	                }
263	                if let Some(keys) = path_platform_keys.get(&rel_path) {
264	                    for key in keys {
265	                        if let Some((_, manifest_rel, role)) = index.platform.get(key).cloned() {
266	                            index
267	                                .platform
268	                                .insert(key.clone(), (current_id.clone(), manifest_rel, role));
269	                        }
270	                    }
271	                }
272	                promoted_siblings
273	                    .entry(name.clone())
274	                    .or_default()
275	                    .extend([(existing_id, existing_set), (current_id, current_set)]);
276	            }
277	        }
278	
279	        let cfg = cfg.with_promoted_siblings(promoted_siblings);
280	
281	        // Tracks, per cfg.package_sets entry (by index), whether it matched at
282	        // least one real discovered package during this walk. A [[package-set]]
283	        // rule that matches nothing is almost always a typo or a stale
284	        // ecosystem prefix (see PackageSetMatchedNothing below) rather than
285	        // intentional, so it must be surfaced instead of silently ignored.
286	        let mut package_set_matched = vec![false; cfg.package_sets.len()];
287	
288	        let mut packages = BTreeMap::new();
289	        for (id, (rel_path, decls)) in package_manifest_decls {
290	            let ch_path = rel_path.join("CHANGELOG.md");
291	            let mut publish_to = Vec::new();
292	            for decl in &decls {
293	                if let Ok(editor) = open_cached(manifest_cache, decl, &ctx) {
294	                    for target in editor.publish_targets() {
295	                        if target != PublishTarget::None && !publish_to.contains(&target) {
296	                            publish_to.push(target);
297	                        }
298	                    }
299	                }
300	            }
301	            if publish_to.is_empty() {
302	                publish_to.push(PublishTarget::None);
303	            }
304	
305	            // The real ecosystem(s) this package's manifests were discovered
306	            // in. `id` may be PackageId::Bare (unpromoted) or PackageId::Prefixed
307	            // (promoted, see SPEC-TRACK3B1-IDENTITY-PROMOTION-CORE); this is the
308	            // only place an ecosystem-prefixed [[package-set]] pattern has
309	            // anything to match against.
310	            let package_ecosystems: Vec<Ecosystem> = decls.iter().map(|d| d.ecosystem()).collect();
311	
312	            // Two-pass specificity search for [[package]] rules (SPEC-002 AC-1/2/3).
313	            // Pass 1: find the first Prefixed rule (pattern.ecosystem().is_some())
314	            //         that matches this package's ID. Prefixed rules always win
315	            //         over Bare rules regardless of declaration order in callisto.toml.
316	            // Pass 2: only if pass 1 found nothing, find the first Bare rule
317	            //         (any rule, since no Prefixed rule matched, the first match
318	            //          is necessarily Bare) that matches this package's ID.
319	            // Within each pass, first-match-wins (TOML declaration order) applies.
320	            let pkg_override = resolve_package_config(&id, &cfg)?;
321	
322	            // Record which [[package-set]] patterns match this package,
323	            // independent of whether a [[package]] rule ends up shadowing the
324	            // fallback below — a pattern that is always shadowed still
325	            // "matched" for the purpose of the zero-match diagnostic.
326	            for (idx, (pattern, _)) in cfg.package_sets.iter().enumerate() {
327	                if pattern.matches_in_ecosystems(id.name(), &package_ecosystems) {
328	                    package_set_matched[idx] = true;
329	                }
330	            }
331	
332	            // If no [[package]] rule matched, look for a [[package-set]] fallback.
333	            // [[package-set]] uses glob patterns and can match many packages at once;
334	            // [[package]] always takes priority over [[package-set]] for the same package.
335	            let set_override = if pkg_override.is_none() {
336	                cfg.package_sets
337	                    .iter()
338	                    .find(|(pattern, _)| pattern.matches_in_ecosystems(id.name(), &package_ecosystems))
339	                    .map(|(_, cfg)| cfg)
340	            } else {
341	                None
342	            };
343	
344	            let active_override = pkg_override.or(set_override);
345	
346	            let release_trigger = active_override
347	                .and_then(|o| o.release_trigger)
348	                .unwrap_or(ReleaseTrigger::Changeset);
349	
350	            let tag_template = active_override.and_then(|o| o.tag_template.clone());
351	
352	            let changelog = if let Some(override_path) = active_override.and_then(|o| o.changelog.as_ref()) {
353	                Some(rel_path.join(override_path))
354	            } else {
355	                Some(ch_path)
356	            };
357	
358	            // Apply the resolved override's publish-to if the operator explicitly set it.
359	            //
360	            // A `[[package]]`/`[[package-set]]` rule has no package context at
361	            // config-parse time (it's just a pattern + string list), so the
362	            // only place the package's real, detected ecosystem is known is
363	            // here, once `decls` (the package's actual manifests) have been
364	            // walked. Reject any configured target whose `.ecosystem()` does
365	            // not match one of the package's detected ecosystems — e.g.
366	            // `publish-to = ["nuget"]` on a Cargo-only crate — rather than
367	            // silently accepting it and having the crate vanish from every
368	            // real publish downstream with zero diagnostic.
369	            if let Some(override_targets) = active_override.and_then(|o| o.publish_to.as_deref()) {
370	                for target in override_targets {
371	                    if let Some(target_ecosystem) = target.ecosystem() {
372	                        if !package_ecosystems.contains(&target_ecosystem) {
373	                            return Err(GraphError::PublishTargetEcosystemMismatch {
374	                                package: id.clone(),
375	                                target: target.config_str().to_string(),
376	                                target_ecosystem,
377	                                package_ecosystems,
378	                            });
379	                        }
380	                    }
381	                }
382	                publish_to = override_targets.to_vec();
383	            }
384	
385	            let pkg = Package {
386	                id: id.clone(),
387	                manifests: decls,
388	                changelog,
389	                release_trigger,
390	                publish_to,
391	                tag_template,
392	            };
393	            packages.insert(id, pkg);
394	        }
395	
396	        // A [[package-set]] rule that matched zero real packages is almost
397	        // always a mistake (e.g. an ecosystem prefix that doesn't correspond
398	        // to any discovered package, or a typo in the glob) rather than
399	        // intentional, so surface it as a visible, non-fatal diagnostic
400	        // instead of letting the rule silently do nothing. This is
401	        // deliberately advisory rather than a hard `GraphError`: a
402	        // `[[package-set]]` rule declared for a monorepo-wide callisto.toml
403	        // can legitimately match nothing when only part of the workspace is
404	        // present (e.g. a partial checkout or filtered walk), and a hard
405	        // error would break that case.
406	        for (idx, (pattern, _)) in cfg.package_sets.iter().enumerate() {
407	            if !package_set_matched[idx] {
408	                diagnostics.push(Diagnostic {
409	                    code: DiagnosticCode::PackageSetMatchedNothing,
410	                    severity: DiagnosticSeverity::Warning,
411	                    message: format!("[[package-set]] `{}` matched no packages", pattern.as_str()),
412	                    package: None,
413	                    path: None,
414	                    escalated_by: None,
415	                    governed_by: None,
416	                });
417	            }
418	        }
419	
420	        // SPEC-002 AC-5: Cross-ecosystem diagnostic pass.
421	        //
422	        // For each bare [[package]] rule in cfg.packages (pattern.ecosystem() == None),
423	        // compute the distinct-ecosystem set: the Ecosystem values found in the canonical
424	        // ManifestDecls of every packages-map entry matched by this rule.
425	        //
426	        // Packages-map keys may be PackageId::Bare or PackageId::Prefixed (a
427	        // promoted package, see SPEC-TRACK3B1-IDENTITY-PROMOTION-CORE). This loop
428	        // remains correct regardless: ecosystem information is always sourced from
429	        // pkg.canonical_manifests(), never from key.ecosystem(), and `pattern`
430	        // here is always unprefixed (prefixed rules `continue` above), so
431	        // pattern.matches(key) matches by name alone independent of whether `key`
432	        // itself is Bare or Prefixed. Do NOT use key.ecosystem().
433	        //
434	        // The primary trigger is a single directory containing both Cargo.toml and
435	        // package.json (the napi case): one packages-map entry with two canonical
436	        // ManifestDecls whose ecosystems are {Cargo, Npm}.
437	        //
438	        // Prefixed [[package]] rules are skipped unconditionally (AC-7).
439	        // [[package-set]] rules are never iterated here (AC-8).
440	        for (pattern, _) in &cfg.packages {
441	            if pattern.ecosystem().is_some() {
442	                continue; // Prefixed rules never trigger this diagnostic (AC-7).
443	            }
444	            let ecosystems: BTreeSet<Ecosystem> = packages
445	                .iter()
446	                .filter(|(key, _)| pattern.matches(key))
447	                // Use the existing Package::canonical_manifests() helper
448	                // (package.rs) which filters to ManifestRole::Canonical.
449	                .flat_map(|(_, pkg)| pkg.canonical_manifests().map(|d| d.ecosystem()))
450	                .collect();
451	            if ecosystems.len() >= 2 {
452	                let eco_list: Vec<&str> = ecosystems.iter().map(|e| e.prefix()).collect();
453	                diagnostics.push(Diagnostic {
454	                    code: DiagnosticCode::BareRuleMatchesMultipleEcosystems,
455	                    severity: DiagnosticSeverity::Warning,
456	                    message: format!(
457	                        "[[package]] rule `{}` matches packages in multiple ecosystems ({}); \
458	                         use an ecosystem-prefixed pattern like `{}/{}` to target only one",
459	                        pattern.name(),
460	                        eco_list.join(", "),
461	                        ecosystems.iter().next().map(|e| e.prefix()).unwrap_or("cargo"),
462	                        pattern.name(),
463	                    ),
464	                    package: None,
465	                    path: None,
466	                    escalated_by: None,
467	                    governed_by: None,
468	                });
469	            }
470	        }
471	
472	        let mut edges = Vec::new();
473	        let mut out_index: BTreeMap<PackageId, Vec<usize>> = BTreeMap::new();
474	        let mut in_index: BTreeMap<PackageId, Vec<usize>> = BTreeMap::new();
475	
476	        for pkg in packages.values() {
477	            for decl in &pkg.manifests {
478	                if decl.role != ManifestRole::Canonical {
479	                    continue;
480	                }
481	                if let Ok(m) = open_cached(manifest_cache, decl, &ctx) {
482	                    for entry in m.iter_dependencies() {
483	                        let (spec, declaring_path) = if entry.inherited {
484	                            if let Some(ref inh) = ctx.cargo_workspace {
485	                                if let Some(inherited_dep) = inh.inherited(&entry.name) {
486	                                    (inherited_dep.spec.clone(), inherited_dep.declared_in.to_path_buf())
487	                                } else {
488	                                    (entry.spec.clone(), decl.path.clone())
489	                                }
490	                            } else {
491	                                (entry.spec.clone(), decl.path.clone())
492	                            }
493	                        } else {
494	                            (entry.spec.clone(), decl.path.clone())
495	                        };
496	
497	                        if let Some(to) =
498	                            index.resolve_native_with_fallback(decl.ecosystem(), &entry.name, &mut diagnostics)
499	                        {
500	                            let idx = edges.len();
501	                            let edge = DepEdge {
502	                                from: pkg.id.clone(),
503	                                to: to.clone(),
504	                                kind: entry.kind,
505	                                spec,
506	                                from_manifest: declaring_path,
507	                                inherited: entry.inherited,
508	                            };
509	                            edges.push(edge);
510	
511	                            out_index.entry(pkg.id.clone()).or_default().push(idx);
512	                            in_index.entry(to.clone()).or_default().push(idx);
513	                        }
514	                    }
515	                }
516	            }
517	        }
518	
519	        if let Some(declared) = locator.declared_edges() {
520	            let cross_diags = crosscheck_declared_edges(&packages, &edges, &declared);
521	            diagnostics.extend(cross_diags);
522	        }
523	
524	        Ok(ManifestWalkResolver {
525	            packages,
526	            edges,
527	            out_index,
528	            in_index,
529	            index,
530	            diagnostics,
531	        })
532	    }
533	}
