535	/// Reads `package.json` at `abs_path` and returns `ManifestRole::Platform`
536	/// when the manifest declares both `os` and `cpu` constraint arrays (the napi
537	/// platform-package convention). Returns `ManifestRole::Canonical` for all
538	/// other npm packages and on any read/parse failure.
539	///
540	/// Note: this performs a second `fs::read` on each npm `package.json` because
541	/// the `manifest_cache` stores `Arc<dyn Manifest>` (which does not expose raw
542	/// JSON fields like `os`/`cpu`) rather than a raw `serde_json::Value`. Fixing
543	/// the redundancy would require a `Manifest::npm_role()` extension method in
544	/// the `callisto-manifests` crate.
545	fn detect_npm_role(abs_path: &Path) -> ManifestRole {
546	    let Ok(bytes) = std::fs::read(abs_path) else {
547	        return ManifestRole::Canonical;
548	    };
549	    let Ok(Value::Object(map)) = serde_json::from_slice(&bytes) else {
550	        return ManifestRole::Canonical;
551	    };
552	
553	    let has_os = map.get("os").and_then(|v| v.as_array()).is_some_and(|a| !a.is_empty());
554	    let has_cpu = map.get("cpu").and_then(|v| v.as_array()).is_some_and(|a| !a.is_empty());
555	
556	    if !has_os || !has_cpu {
557	        return ManifestRole::Canonical;
558	    }
559	
560	    let Some(platform) = map
561	        .get("os")
562	        .and_then(|v| v.as_array())
563	        .and_then(|a| a.first())
564	        .and_then(|v| v.as_str())
565	        .map(str::to_string)
566	    else {
567	        return ManifestRole::Canonical;
568	    };
569	
570	    let Some(arch) = map
571	        .get("cpu")
572	        .and_then(|v| v.as_array())
573	        .and_then(|a| a.first())
574	        .and_then(|v| v.as_str())
575	        .map(str::to_string)
576	    else {
577	        return ManifestRole::Canonical;
578	    };
579	
580	    // npm's standard `os`/`cpu` manifest fields have no libc/ABI concept at
581	    // all, so a real disk-discovered Linux napi platform package always
582	    // produced `abi: None` here -- but `napi.rs::role_to_triple`'s Linux
583	    // match arms all require a concrete ABI, meaning such a package could
584	    // never resolve to its triple. napi-rs's own package-generation
585	    // convention encodes the ABI in the package *name*'s suffix instead
586	    // (e.g. "@scope/pkg-linux-x64-gnu"), so infer it from there when the
587	    // platform is linux.
588	    let abi = if platform == "linux" {
589	        map.get("name")
590	            .and_then(|v| v.as_str())
591	            .and_then(napi_linux_abi_from_package_name)
592	    } else {
593	        None
594	    };
595	
596	    ManifestRole::Platform { platform, arch, abi }
597	}
598	
599	/// Infers a Linux napi-rs platform package's libc ABI from its package
600	/// name's trailing suffix. Returns `None` when the name has no recognized
601	/// suffix -- this infers when the signal is present, it doesn't invent an
602	/// ABI that isn't actually there.
603	fn napi_linux_abi_from_package_name(name: &str) -> Option<String> {
604	    for abi in ["gnueabihf", "gnu", "musl"] {
605	        if name.ends_with(&format!("-{abi}")) {
606	            return Some(abi.to_string());
607	        }
608	    }
609	    None
610	}
611	
612	/// Explicit ecosystem precedence for primary-ID selection when a single
613	/// project directory contains manifests from multiple ecosystems (e.g., both
614	/// `Cargo.toml` and `package.json`). Lower value = higher priority.
615	///
616	/// Precedence: Cargo (0) > Npm (1) > Pypi (2) > others (255).
617	///
618	/// This function is used instead of `Ecosystem`'s derived `Ord` so that the
619	/// ordering is stable even if the `Ecosystem` variant sequence changes.
620	fn ecosystem_primary_priority(e: Ecosystem) -> u8 {
621	    match e {
622	        Ecosystem::Cargo => 0,
623	        Ecosystem::Npm => 1,
624	        Ecosystem::Pypi => 2,
625	        _ => u8::MAX,
626	    }
627	}
