637	                root.join(rel).join("Cargo.toml"),
638	                format!("[package]\nname = \"{name}\"\nversion = \"0.1.0\"\nedition = \"2021\"\n"),
639	            )
640	            .unwrap(),
641	            Ecosystem::Npm => std::fs::write(
642	                root.join(rel).join("package.json"),
643	                format!(r#"{{"name":"{name}","version":"0.1.0"}}"#),
644	            )
645	            .unwrap(),
646	            Ecosystem::Pypi => std::fs::write(
647	                root.join(rel).join("pyproject.toml"),
648	                format!("[project]\nname = \"{name}\"\nversion = \"0.1.0\"\n"),
649	            )
650	            .unwrap(),
651	            _ => unreachable!(),
652	        }
653	    }
