730	    /// End-to-end: a real disk-discovered napi platform manifest (Case D --
731	    /// a `Cargo.toml` and a differently-named `package.json` sharing one
732	    /// directory, the platform npm package's own identity distinct from the
733	    /// owning crate's) must resolve through `[[fixed-group]] members`
734	    /// naming the platform package by its own npm name, via
735	    /// `IdentityIndex.platform` -- not the hand-constructed
736	    /// `GroupMember::PlatformManifest` fixtures other tests use, which
737	    /// bypass this wiring entirely and would not have caught the gap this
738	    /// test pins.
739	    #[test]
740	    fn real_platform_manifest_resolves_via_fixed_group_and_feeds_napi_drift() {
741	        let dir = tempfile::tempdir().expect("tempdir");
742	        let root = dir.path();
743	
744	        std::fs::write(
745	            root.join("Cargo.toml"),
746	            "[package]\nname = \"my-crate\"\nversion = \"0.1.0\"\nedition = \"2021\"\n",
747	        )
748	        .unwrap();
749	        std::fs::write(
750	            root.join("package.json"),
751	            r#"{"name":"@myorg/my-crate-linux-x64-gnu","version":"0.1.0","os":["linux"],"cpu":["x64"]}"#,
752	        )
753	        .unwrap();
754	        std::fs::write(
755	            root.join("callisto.toml"),
756	            "[[fixed-group]]\nname = \"my-group\"\nmembers = [\"my-crate\", \"@myorg/my-crate-linux-x64-gnu\"]\n",
757	        )
758	        .unwrap();
759	
760	        let locator = crate::locate::IgnoreWalkLocator::new(root);
761	        let runner = NoopRunner;
762	        let ws = crate::Workspace::load(root.to_path_buf(), &locator, &runner)
763	            .expect("group resolution must succeed now that the real platform manifest resolves");
764	
765	        let group = ws
766	            .config
767	            .groups
768	            .fixed
769	            .get(&callisto_model::GroupName("my-group".to_string()))
770	            .expect("fixed group must exist");
771	
772	        let platform_member = group
773	            .members
774	            .iter()
775	            .find(|m| matches!(m, crate::config::groups::GroupMember::PlatformManifest { .. }))
776	            .expect("platform member must resolve, not be silently dropped or errored");
777	
778	        let crate::config::groups::GroupMember::PlatformManifest { role, name, .. } = platform_member else {
779	            unreachable!()
780	        };
781	        assert_eq!(name, "@myorg/my-crate-linux-x64-gnu");
782	        assert_eq!(
783	            crate::napi::role_to_triple(role).as_deref(),
784	            Some("x86_64-unknown-linux-gnu"),
785	            "role must be the real, disk-derived role, not the old hardcoded \
786	             platform=\"unknown\" stub -- got: {role:?}"
787	        );
788	
789	        // Feed straight into napi_drift, matching the task's own framing:
790	        // "napi_drift receives real group members".
791	        let declared = vec!["x86_64-unknown-linux-gnu".to_string()];
792	        let diagnostics = crate::napi::napi_drift(group, &declared, root);
793	        assert!(
794	            diagnostics.is_empty(),
795	            "declared napi.targets matches the real group member; expected no drift \
796	             diagnostics, got: {diagnostics:?}"
797	        );
798	    }
