813	        let root = dir.path();
814	
815	        std::fs::write(
816	            root.join("Cargo.toml"),
817	            "[package]\nname = \"my-crate\"\nversion = \"0.1.0\"\nedition = \"2021\"\n",
818	        )
819	        .unwrap();
820	        std::fs::write(
821	            root.join("package.json"),
822	            r#"{"name":"@myorg/my-crate-linux-x64-gnu","version":"0.1.0","os":["linux"],"cpu":["x64"]}"#,
823	        )
824	        .unwrap();
825	
826	        std::fs::create_dir_all(root.join("consumer")).unwrap();
827	        std::fs::write(
828	            root.join("consumer/package.json"),
829	            r#"{"name":"@myorg/consumer","version":"0.1.0","optionalDependencies":{"@myorg/my-crate-linux-x64-gnu":"0.1.0"}}"#,
830	        )
831	        .unwrap();
832	
833	        let locator = crate::locate::IgnoreWalkLocator::new(root);
834	        let runner = NoopRunner;
835	        let ws = crate::Workspace::load(root.to_path_buf(), &locator, &runner).expect("workspace load must succeed");
836	
