75	fn detect_fingerprint(content: &str) -> FormatFingerprint {
76	    let line_ending = if content.contains("\r\n") {
77	        LineEnding::CrLf
78	    } else {
79	        LineEnding::Lf
80	    };
81	
82	    let trailing_newline = content.ends_with('\n');
83	
84	    let mut indent = Indent::DefaultTwoSpaces;
85	    for line in content.lines() {
86	        let trimmed_start = line.trim_start();
87	        if trimmed_start.starts_with('"') && line.len() > trimmed_start.len() {
88	            let leading = &line[..line.len() - trimmed_start.len()];
89	            if leading.contains('\t') {
90	                indent = Indent::Tabs;
91	            } else {
92	                indent = Indent::Spaces(leading.len() as u8);
93	            }
94	            break;
95	        }
96	    }
97	
98	    let has_bom = content.starts_with('\u{FEFF}');
99	    FormatFingerprint {
100	        indent,
101	        trailing_newline,
102	        line_ending,
103	        has_bom,
104	    }
105	}
