107	fn format_json_pretty(map: &IndexMap<&String, &Value>, indent_str: &str) -> Result<String, ManifestError> {
108	    use serde::Serialize;
109	    let buf = Vec::new();
110	    let formatter = serde_json::ser::PrettyFormatter::with_indent(indent_str.as_bytes());
111	    let mut serializer = serde_json::Serializer::with_formatter(buf, formatter);
112	    map.serialize(&mut serializer)
113	        .map_err(|e| ManifestError::FormattingNotPreserved {
114	            path: std::path::PathBuf::new(),
115	            message: format!("JSON serialization failed: {e}"),
116	        })?;
117	    let bytes = serializer.into_inner();
118	    let mut out = String::from_utf8(bytes).map_err(|e| ManifestError::FormattingNotPreserved {
119	        path: std::path::PathBuf::new(),
120	        message: format!("JSON serialization produced invalid UTF-8: {e}"),
121	    })?;
122	    out.push('\n');
123	    Ok(out)
124	}
