126	/// Extracts `name` from an already-parsed `package.json` document. Pure and
127	/// I/O-free -- see [`crate::cargo::cargo_package_name`]'s doc comment for
128	/// why this exists as a standalone function rather than only living inside
129	/// [`Manifest::package_name`].
130	pub fn npm_package_name(doc: &serde_json::Map<String, serde_json::Value>) -> Option<&str> {
131	    doc.get("name").and_then(|n| n.as_str())
132	}
