134	/// [`crate::read_identity`]'s `package.json` implementation: parses
135	/// `source` and extracts `name` plus a [`crate::VersionSource::Literal`]
136	/// for `version` (npm has no workspace-inherited-version concept, unlike
137	/// Cargo).
138	pub(crate) fn identity_from_source(source: &str, path: &Path) -> Result<crate::ManifestIdentity, ManifestError> {
139	    let clean = source.strip_prefix('\u{FEFF}').unwrap_or(source);
140	    let doc: Map<String, Value> = serde_json::from_str(clean).map_err(|e| ManifestError::Parse {
141	        path: path.to_path_buf(),
142	        format: ManifestFormat::PackageJson,
143	        message: e.to_string(),
144	    })?;
145	
146	    let name = npm_package_name(&doc).map(str::to_string);
147	    let version = doc
148	        .get("version")
149	        .and_then(|v| v.as_str())
150	        .map(|s| crate::VersionSource::Literal(s.to_string()));
151	
152	    Ok(crate::ManifestIdentity { name, version })
153	}
