155	/// Reads `napi.targets` from an already-parsed `package.json` value.
156	/// `Ok(None)` when `napi` or `napi.targets` is absent -- not every napi
157	/// package.json declares platform targets. `Err` when `napi.targets` is
158	/// present but is not a JSON array of strings.
159	///
160	/// The single implementation both `NapiTargetsIndex::load` (lenient: `.ok()`
161	/// this, treating a malformed value the same as absent) and
162	/// `matrix::read_napi_targets` (strict: propagates the error) build their
163	/// differing policies on top of -- see each call site for which it chooses.
164	pub fn read_napi_targets(path: &Path, val: &Value) -> Result<Option<Vec<String>>, ManifestError> {
165	    let Some(napi) = val.get("napi") else {
166	        return Ok(None);
167	    };
168	    let Some(targets) = napi.get("targets") else {
169	        return Ok(None);
170	    };
171	
172	    let arr = targets.as_array().ok_or_else(|| ManifestError::Parse {
173	        path: path.to_path_buf(),
174	        format: ManifestFormat::PackageJson,
175	        message: "napi.targets must be a JSON array of strings".to_string(),
176	    })?;
177	
178	    let mut out = Vec::with_capacity(arr.len());
179	    for item in arr {
180	        let s = item.as_str().ok_or_else(|| ManifestError::Parse {
181	            path: path.to_path_buf(),
182	            format: ManifestFormat::PackageJson,
183	            message: "napi.targets entries must all be strings".to_string(),
184	        })?;
185	        out.push(s.to_string());
186	    }
187	    Ok(Some(out))
188	}
