191	    fn persist(&mut self, permit: &ApplyPermit) -> Result<(), ManifestError> {
192	        let indent_str = match self.fingerprint.indent {
193	            Indent::Spaces(n) => " ".repeat(n as usize),
194	            Indent::Tabs => "\t".to_string(),
195	            Indent::DefaultTwoSpaces => "  ".to_string(),
196	        };
197	
198	        let mut map = IndexMap::new();
199	        for (k, v) in &self.doc {
200	            map.insert(k, v);
201	        }
202	
203	        let mut out = format_json_pretty(&map, &indent_str)?;
204	        if self.fingerprint.line_ending == LineEnding::CrLf {
205	            out = out.replace("\r\n", "\n").replace('\n', "\r\n");
206	        }
207	
208	        if !self.fingerprint.trailing_newline && out.ends_with('\n') {
209	            if out.ends_with("\r\n") {
210	                out.truncate(out.len() - 2);
211	            } else {
212	                out.truncate(out.len() - 1);
213	            }
214	        }
215	
216	        if self.fingerprint.has_bom {
217	            out = format!("\u{FEFF}{}", out);
218	        }
219	
220	        crate::atomic::atomic_write(&self.absolute, &out, permit).map_err(|e| ManifestError::Write {
221	            path: self.path.clone(),
222	            message: e.to_string(),
223	        })?;
224	        crate::record_persist_call();
225	        Ok(())
226	    }
