248	    fn publish_targets(&self) -> Vec<callisto_model::PublishTarget> {
249	        if !self.is_publishable() {
250	            return vec![callisto_model::PublishTarget::None];
251	        }
252	        // Read `publishConfig.registry` from package.json, the standard npm
253	        // mechanism for targeting a private registry. When set, `npm publish`
254	        // must receive `--registry <url>`; when absent, the public registry is
255	        // used (npm's built-in default).
256	        let publish_config = self.doc.get("publishConfig");
257	        let registry = publish_config
258	            .and_then(|pc| pc.get("registry"))
259	            .and_then(|r| r.as_str())
260	            .map(|s| s.to_string());
261	        // Read `publishConfig.access` to propagate the operator's explicit
262	        // access intent. npm's `--access` CLI flag overrides publishConfig.access,
263	        // so callisto must read it here and honour it in plan_publish rather than
264	        // blindly passing `--access public` for all scoped packages. Any value
265	        // other than the two npm recognises (including absence) is `None`,
266	        // not an error -- an unrecognised value here isn't this layer's job
267	        // to validate.
268	        let access = publish_config
269	            .and_then(|pc| pc.get("access"))
270	            .and_then(|a| a.as_str())
271	            .and_then(|s| match s {
272	                "public" => Some(callisto_model::NpmAccess::Public),
273	                "restricted" => Some(callisto_model::NpmAccess::Restricted),
