296	            .ok_or_else(|| ManifestError::MissingField {
297	                path: self.path.clone(),
298	                field: "version",
299	            })?;
300	
301	        Version::parse(raw, VersionGrammar::SemVer).map_err(|source| ManifestError::InvalidVersion {
302	            path: self.path.clone(),
303	            raw: raw.to_string(),
304	            source,
305	        })
306	    }
307	
308	    fn write_version(&mut self, v: &Version, _permit: &ApplyPermit) -> Result<(), ManifestError> {
309	        self.doc
310	            .insert("version".to_string(), Value::String(v.render().to_string()));
311	        Ok(())
312	    }
313	
314	    fn iter_dependencies(&self) -> Box<dyn Iterator<Item = DependencyEntry> + '_> {
315	        let mut entries = Vec::new();
316	
317	        for (section_name, kind) in [
318	            ("dependencies", DepKind::Runtime),
319	            ("devDependencies", DepKind::Dev),
320	            ("peerDependencies", DepKind::Peer),
321	            ("optionalDependencies", DepKind::Optional),
322	        ] {
323	            if let Some(obj) = self.doc.get(section_name).and_then(|v| v.as_object()) {
324	                for (name, val) in obj {
325	                    if let Some(v_str) = val.as_str() {
326	                        let spec = parse_npm_spec_str(v_str, self.npm_workspace_kind);
327	                        entries.push(DependencyEntry {
328	                            name: name.clone(),
329	                            kind,
330	                            spec,
331	                            inherited: false,
332	                        });
333	                    }
334	                }
335	            }
336	        }
337	
338	        Box::new(entries.into_iter())
339	    }
340	
341	    fn update_dependency_spec(
342	        &mut self,
343	        name: &str,
344	        kind: DepKind,
345	        new: DepSpec,
346	        _permit: &ApplyPermit,
347	    ) -> Result<(), ManifestError> {
348	        if kind == DepKind::Build {
349	            return Err(ManifestError::DependencyNotFound {
350	                path: self.path.clone(),
351	                name: name.to_string(),
352	                kind,
353	            });
354	        }
355	
356	        let section_name = match kind {
357	            DepKind::Runtime => "dependencies",
358	            DepKind::Dev => "devDependencies",
359	            DepKind::Peer => "peerDependencies",
360	            DepKind::Optional => "optionalDependencies",
361	            DepKind::Build => unreachable!(),
362	        };
363	
364	        // Validate that the target dependency actually exists in the primary
365	        // section *before* mutating anything. This guarantees that a failed
366	        // update (dependency not found) leaves self.doc byte-for-byte
367	        // unchanged, including the overrides/resolutions tables below.
368	        let updated_in_section = self
369	            .doc
370	            .get(section_name)
371	            .and_then(|v| v.as_object())
372	            .is_some_and(|section| section.contains_key(name));
373	
374	        if !updated_in_section {
375	            return Err(ManifestError::DependencyNotFound {
376	                path: self.path.clone(),
377	                name: name.to_string(),
378	                kind,
379	            });
380	        }
381	
382	        if let Some(section) = self.doc.get_mut(section_name).and_then(|v| v.as_object_mut()) {
383	            section.insert(name.to_string(), Value::String(new.render()));
384	        }
385	
386	        for extra in ["overrides", "resolutions"] {
387	            if let Some(tbl) = self.doc.get_mut(extra).and_then(|v| v.as_object_mut()) {
388	                if tbl.get(name).is_some_and(|v| v.is_string()) {
389	                    tbl.insert(name.to_string(), Value::String(new.render()));
390	                }
391	            }
392	        }
393	
394	        Ok(())
395	    }
396	
397	    fn update_optional_dependencies(
398	        &mut self,
399	        updates: &[(String, Version)],
400	        _permit: &ApplyPermit,
401	    ) -> Result<(), ManifestError> {
402	        let section = self
403	            .doc
404	            .entry("optionalDependencies".to_string())
405	            .or_insert_with(|| Value::Object(Map::new()))
406	            .as_object_mut()
407	            .ok_or_else(|| ManifestError::FormattingNotPreserved {
408	                path: self.path.clone(),
409	                message: "optionalDependencies is not an object".to_string(),
410	            })?;
411	
412	        for (name, ver) in updates {
413	            section.insert(name.clone(), Value::String(ver.render().to_string()));
414	        }
415	
416	        Ok(())
417	    }
418	}
419	
420	fn parse_npm_spec_str(s: &str, ws_kind: Option<WorkspaceKind>) -> DepSpec {
421	    if let Some(rest) = s.strip_prefix("workspace:") {
422	        if let Some(kind) = ws_kind {
423	            return DepSpec::Workspace(kind);
424	        }
425	        return DepSpec::Opaque(format!("workspace:{rest}"));
426	    }
427	    if let Some(rest) = s.strip_prefix("catalog:") {
428	        let name = if rest.is_empty() { None } else { Some(rest.to_string()) };
429	        return DepSpec::Catalog(name);
430	    }
431	
432	    if crate::common::is_bare_semver(s) {
433	        if let Ok(v) = Version::parse(s, VersionGrammar::SemVer) {
434	            return DepSpec::Exact(v);
435	        }
436	    }
437	
438	    if let Ok(req) = VersionReq::parse(s, Ecosystem::Npm) {
439	        return DepSpec::Range(req, s.to_string());
440	    }
441	
442	    DepSpec::Opaque(s.to_string())
443	}
444	
445	pub fn round_trip(spec: &DepSpec, target: &Version) -> Option<DepSpec> {
446	    match spec {
447	        DepSpec::Exact(_) => Some(DepSpec::Exact(target.clone())),
448	        DepSpec::Range(_, original) => {
449	            let (prefix, rest) = crate::common::split_single_operator_prefix(original)?;
450	            if rest.contains(' ') || rest.contains('-') || rest.contains('|') || rest.contains(['x', 'X', '*']) {
451	                return None;
452	            }
453	            let rendered = format!("{prefix}{}", render_at_precision(target, rest));
454	            let req = VersionReq::parse(&rendered, Ecosystem::Npm).ok()?;
455	            Some(DepSpec::Range(req, rendered))
456	        }
457	        _ => None,
458	    }
459	}
460	
461	fn render_at_precision(target: &Version, original_clause: &str) -> String {
462	    if target.is_prerelease() {
463	        return target.render().to_string();
464	    }
465	    let parts: Vec<&str> = original_clause.split('.').collect();
466	    let maj = target.major().unwrap_or(0);
467	    let min = target.minor().unwrap_or(0);
468	    let pat = target.patch().unwrap_or(0);
469	
470	    match parts.len() {
471	        1 => format!("{maj}"),
472	        2 => format!("{maj}.{min}"),
473	        _ => format!("{maj}.{min}.{pat}"),
474	    }
475	}
476	
477	pub fn detect_npm_workspace_kind(workspace_root: &Path) -> Result<Option<WorkspaceKind>, ManifestError> {
478	    if workspace_root.join("pnpm-lock.yaml").exists() {
479	        return Ok(Some(WorkspaceKind::Pnpm));
480	    }
481	    if workspace_root.join("yarn.lock").exists() {
482	        return Ok(Some(WorkspaceKind::Yarn));
483	    }
484	    if workspace_root.join("package-lock.json").exists() {
485	        return Ok(Some(WorkspaceKind::Npm));
486	    }
487	
488	    let root_pkg_json = workspace_root.join("package.json");
489	    if root_pkg_json.exists() {
490	        if let Ok(content) = fs::read_to_string(&root_pkg_json) {
491	            if let Ok(val) = serde_json::from_str::<Value>(&content) {
492	                if val.get("workspaces").is_some() {
493	                    return Ok(Some(WorkspaceKind::Npm));
494	                }
495	            }
496	        }
497	    }
498	
499	    Ok(None)
500	}
