1	//! Per-ecosystem manifest read/write for callisto.
2	
3	use std::path::Path;
4	use std::sync::Arc;
5	
6	use callisto_model::{
7	    ApplyPermit, DepSpec, Ecosystem, ManifestDecl, ManifestError, ManifestFormat, ManifestRole, Version, WorkspaceKind,
8	};
9	
10	pub mod atomic;
11	
12	pub mod cargo;
13	mod common;
14	pub mod npm;
15	pub mod python;
16	
17	pub use cargo::{cargo_package_name, CargoToml, InheritedDep, WorkspaceCargoResolver, WorkspaceInheritance};
18	pub use npm::{detect_npm_workspace_kind, npm_package_name, read_napi_targets, PackageJson};
19	pub use python::{python_package_name, PyprojectToml, Requirement};
20	
21	/// Package identity extracted directly from manifest source text via
22	/// [`read_identity`], without going through the full `Manifest::open`
23	/// lifecycle (workspace-inheritance context, on-disk path resolution,
24	/// atomic-write machinery). For callers that already hold a manifest's
25	/// content as a string -- a `git show` blob, a walker's pre-read buffer --
26	/// and only need the package's name and/or where its version comes from.
27	#[derive(Clone, Debug, Default, PartialEq, Eq)]
28	pub struct ManifestIdentity {
29	    pub name: Option<String>,
30	    pub version: Option<VersionSource>,
31	}
32	
33	/// Where a manifest's version declaration comes from. Distinct from a raw
34	/// `Option<String>` so Cargo's `version.workspace = true` is a real,
35	/// distinguishable case instead of being silently collapsed into "no
36	/// version present". [`read_identity`] never resolves the inherited value
37	/// (it has no workspace context) -- callers needing the resolved version
38	/// go through `Manifest::current_version` instead.
39	#[derive(Clone, Debug, PartialEq, Eq)]
40	pub enum VersionSource {
41	    Literal(String),
42	    InheritedFromWorkspace,
43	}
44	
45	/// Extracts a package's name and version source directly from `source`,
46	/// the raw text of a manifest matching `format`. Pure and I/O-free.
47	///
48	/// Replaces hand-parsing `Cargo.toml`/`package.json`/`pyproject.toml` at
49	/// call sites that already hold manifest content as a string rather than a
50	/// path `open()` can read from disk (audit pattern B) -- e.g. a `git show`
51	/// blob, or a directory-walker's pre-read buffer.
52	///
53	/// `path` is used only to build accurate `ManifestError::Parse` locations
54	/// on a parse failure; it need not exist on disk. Only the three
55	/// canonical-identity formats ([`Ecosystem::CANONICAL`]) are supported --
56	/// any other format returns `Err(ManifestError::ReadOnlyFormat)`.
57	pub fn read_identity(format: ManifestFormat, source: &str, path: &Path) -> Result<ManifestIdentity, ManifestError> {
58	    match format {
59	        ManifestFormat::CargoToml => cargo::identity_from_source(source, path),
60	        ManifestFormat::PackageJson => npm::identity_from_source(source, path),
61	        ManifestFormat::PyprojectToml => python::identity_from_source(source, path),
62	        other => Err(ManifestError::ReadOnlyFormat {
63	            path: path.to_path_buf(),
64	            format: other,
65	            reason: "read_identity only supports the three canonical-identity manifest formats \
66	                     (Cargo.toml, package.json, pyproject.toml)",
67	        }),
68	    }
69	}
70	
71	/// Trait implemented by per-ecosystem manifest editors.
72	pub trait Manifest: Send + Sync {
73	    fn path(&self) -> &Path;
74	    fn ecosystem(&self) -> Ecosystem;
75	    fn role(&self) -> ManifestRole;
76	    fn package_name(&self) -> Result<String, ManifestError>;
77	    fn current_version(&self) -> Result<Version, ManifestError>;
78	    fn write_version(&mut self, v: &Version, permit: &ApplyPermit) -> Result<(), ManifestError>;
79	    fn persist(&mut self, permit: &ApplyPermit) -> Result<(), ManifestError>;
80	    fn iter_dependencies(&self) -> Box<dyn Iterator<Item = callisto_model::DependencyEntry> + '_>;
81	    fn update_dependency_spec(
82	        &mut self,
83	        name: &str,
84	        kind: callisto_model::DepKind,
85	        new: DepSpec,
86	        permit: &ApplyPermit,
87	    ) -> Result<(), ManifestError>;
88	    fn is_publishable(&self) -> bool {
89	        true
90	    }
91	    fn publish_targets(&self) -> Vec<callisto_model::PublishTarget> {
92	        if !self.is_publishable() {
93	            return vec![callisto_model::PublishTarget::None];
94	        }
95	        match self.ecosystem() {
96	            Ecosystem::Cargo => vec![callisto_model::PublishTarget::CratesIo],
97	            Ecosystem::Npm => vec![callisto_model::PublishTarget::Npm {
98	                registry: None,
99	                access: None,
100	            }],
101	            _ => vec![callisto_model::PublishTarget::None],
102	        }
103	    }
104	    fn update_optional_dependencies(
105	        &mut self,
106	        updates: &[(String, Version)],
107	        permit: &ApplyPermit,
108	    ) -> Result<(), ManifestError>;
109	}
110	
111	/// Context passed to open() to supply workspace-wide inheritance facts.
112	pub struct OpenContext<'a> {
113	    pub workspace_root: &'a Path,
114	    pub cargo_workspace: Option<Arc<WorkspaceInheritance>>,
115	    pub npm_workspace_kind: Option<WorkspaceKind>,
116	}
117	
118	impl<'a> OpenContext<'a> {
119	    /// Builds an [`OpenContext`] rooted at `root` by resolving Cargo
120	    /// workspace inheritance (when `root/Cargo.toml` exists) and detecting
121	    /// the npm workspace kind. This is the single reusable constructor for
122	    /// the "check Cargo.toml exists, load workspace inheritance, detect npm
123	    /// workspace kind" sequence that call sites previously reimplemented
124	    /// independently (audit pattern: duplication) -- see
125	    /// `callisto-graph`'s `walk`, `lib` (`Workspace::base_versions`),
126	    /// `apply`, and `commands::version` modules.
127	    pub fn for_workspace_root(root: &'a Path) -> OpenContext<'a> {
128	        let cargo_workspace = if root.join("Cargo.toml").exists() {
129	            if let Ok(resolver) = WorkspaceCargoResolver::load(&root.join("Cargo.toml")) {
130	                resolver.inheritance().ok().map(Arc::new)
131	            } else {
132	                None
133	            }
134	        } else {
135	            None
136	        };
137	
138	        let npm_workspace_kind = detect_npm_workspace_kind(root).ok().flatten();
139	
140	        OpenContext {
141	            workspace_root: root,
142	            cargo_workspace,
143	            npm_workspace_kind,
144	        }
145	    }
146	}
147	
148	/// Test-observability counter: total number of times [`open`] has been
149	/// invoked. Production code never reads this; it exists so callers (in
150	/// particular, callers building a caching layer on top of `open()`) can
151	/// write regression tests asserting that a given manifest path is opened
152	/// (read + parsed from disk) at most once per logical operation, instead of
153	/// once per call site. See `callisto-graph`'s `manifest_cache` module.
154	static OPEN_CALL_COUNT: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
155	
156	/// Resets the internal manifest-open call counter to zero. Intended for use in test setup.
157	pub fn reset_open_call_count() {
158	    OPEN_CALL_COUNT.store(0, std::sync::atomic::Ordering::SeqCst);
159	}
160	
161	/// Reads the current value of the internal manifest-open call counter.
162	pub fn open_call_count() -> usize {
163	    OPEN_CALL_COUNT.load(std::sync::atomic::Ordering::SeqCst)
164	}
165	
166	/// Test-observability counter: total number of times a `Manifest`
167	/// implementor's `persist` has returned `Ok`. Production code never reads
168	/// this; it exists so callers can write regression tests asserting a given
169	/// manifest path is flushed to disk at most once per logical operation.
170	/// Distinct from `OPEN_CALL_COUNT` so open-count and persist-count
171	/// assertions in the same test are independent.
172	static PERSIST_CALL_COUNT: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
173	
174	/// Resets the internal manifest-persist call counter to zero. Intended for use in test setup.
175	pub fn reset_persist_call_count() {
176	    PERSIST_CALL_COUNT.store(0, std::sync::atomic::Ordering::SeqCst);
177	}
178	
179	/// Reads the current value of the internal manifest-persist call counter.
180	pub fn persist_call_count() -> usize {
181	    PERSIST_CALL_COUNT.load(std::sync::atomic::Ordering::SeqCst)
182	}
183	
184	/// Increments PERSIST_CALL_COUNT by one. Called by each Manifest
185	/// implementor's persist() immediately after its own atomic_write returns
186	/// Ok; PERSIST_CALL_COUNT itself is private to this module, so this is the
187	/// only way other modules in this crate may increment it.
188	pub(crate) fn record_persist_call() {
189	    PERSIST_CALL_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
190	}
191	
192	/// Opens a manifest file matching `decl.format`.
193	pub fn open(decl: &ManifestDecl, ctx: &OpenContext<'_>) -> Result<Box<dyn Manifest>, ManifestError> {
194	    OPEN_CALL_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
195	    if decl.role == ManifestRole::Lockfile {
196	        return Err(ManifestError::ReadOnlyFormat {
197	            path: decl.path.clone(),
198	            format: decl.format,
199	            reason: "lockfiles are regenerated via subprocess (§7.6 step 9), never opened as a Manifest handle",
200	        });

